public void testPerformance() {
    //Reduced values to fix STANBOL-
    MGraph sg = new SimpleMGraph();
    //reduced from 1000
    int iterations = 100;
    int graphsize = 100000;
    Long seed = System.currentTimeMillis();
    log.info("Test Seed: {}", seed);
    createGraph(sg, graphsize, seed);
