/**
 * This uploads the HTML as well as the plain text version of an content.
 * This allows it CMS to parse already available alternate content versions
 * in a single request. Stanbol can than still use the original content
 * (e.g. to extract metadata) but other engines that require the alternate
 * version (e.g. plain text version) of an document will directly use the
 * parsed version .<p>
 * This UnitTest ensures this by adding a "secret" extension the to plain
 * text version and than checks if the two entities mentioned in that
 * part are included in the extracted entities.
 * @throws IOException
 */
@Test
public void testUploadMultipleContents() throws IOException {
    //It is a secret, that Berlin is the capital of Germany
    String extraTextConent = TEXT_CONTENT + "\nIt is a secret, that the city of Berlin is the capital of Germany since 1990.";
    //The multipart entity for the contentItem
    MultipartEntity contentItem = new MultipartEntity(null, null, UTF8);
    //The multipart/alternate mime part for the parsed content versions
    HttpMultipart content = new HttpMultipart("alternate", UTF8, "contentParts");
    //add the content part to the contentItem
    contentItem.addPart(//the name MUST BE "content"
    "content", new MultipartContentBody(content));
    //now add the content (ordering is important, because the first
    //part will be assumed the original document and all following are
    //assumed alternate - transformed - versions
    content.addBodyPart(new FormBodyPart(//the id of the content
    "http://www.example.com/test.html", new StringBody(HTML_CONTENT, "text/html", UTF8)));
    content.addBodyPart(new FormBodyPart("http://www.example.com/test.txt", new StringBody(extraTextConent, "text/plain", UTF8)));
    String receivedContent = executor.execute(builder.buildPostRequest(getEndpoint()).withHeader("Accept", "text/rdf+nt").withEntity(contentItem)).assertStatus(200).assertContentRegexp(//and the expected enhancements in the metadata
    "http://purl.org/dc/terms/creator.*LangIdEnhancementEngine", "http://purl.org/dc/terms/language.*en", "http://fise.iks-project.eu/ontology/entity-label.*Paris", "http://purl.org/dc/terms/creator.*org.apache.stanbol.enhancer.engines.opennlp.*EngineCore", "http://fise.iks-project.eu/ontology/entity-label.*Bob Marley", //check also for expeted entities extracted from the secret Text part!
    "http://fise.iks-project.eu/ontology/entity-label.*Berlin", "http://fise.iks-project.eu/ontology/entity-label.*Germany").getContent();
    log.debug("Content:\n{}\n", receivedContent);
}

