/**
 * Stanbol also supports to upload pre-existing metadata with the content.
 * This UnitTest uses an example that parsed TextAnnotations for free text
 * tags provided by users that are than linked to Entities in DBPedia
 * @throws IOException
 */
@Test
public void testUploadWithMetadata() throws IOException {
    //create the metadata
    Resource user = new PlainLiteralImpl("Rupert Westenthaler");
    final UriRef contentItemId = new UriRef("http://www.example.com/test.html");
    MGraph metadata = new SimpleMGraph();
    addTagAsTextAnnotation(metadata, contentItemId, "Germany", DBPEDIA_PLACE, user);
    addTagAsTextAnnotation(metadata, contentItemId, "Europe", DBPEDIA_PLACE, user);
    addTagAsTextAnnotation(metadata, contentItemId, "NATO", DBPEDIA_ORGANISATION, user);
    addTagAsTextAnnotation(metadata, contentItemId, "Silvio Berlusconi", DBPEDIA_PERSON, user);
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    serializer.serialize(out, metadata, SupportedFormat.RDF_XML);
    String rdfContent = new String(out.toByteArray(), UTF8);
    //The multipart entity for the contentItem
    MultipartEntity contentItem = new MultipartEntity(null, null, UTF8);
    //the "metadata" MUST BE the first element
    /*
         * NOTE: We need here to override the getFilename, because this MUST
         *       BE the URI of the ContentItem. This is important, because the
         *       Metadata do contain triples about that ContentItem and therefore
         *       it MUST BE assured that the URI of the ContentItem created by
         *       the Stanbol Enhancer is the same of as the URI used in the
         *       Metadata!
         */
    contentItem.addPart(//the name MUST BE "metadata"
    "metadata", new StringBody(rdfContent, SupportedFormat.RDF_XML, UTF8) {

        @Override
        public String getFilename() {
            //The filename MUST BE the
            //uri of the ContentItem
            return contentItemId.getUnicodeString();
        }
    });
    //Add the Content
    /*
         * NOTE: If we only parse a single content than we can also directly
         *       add it with the name "content". This means that the useage of
         *       a "multipart/alternate" container is in such cases optional.
         */
    contentItem.addPart(//the name MUST BE "content"
    "content", new StringBody(HTML_CONTENT, "text/html", UTF8));
    //send the request
    String receivedContent = executor.execute(builder.buildPostRequest(getEndpoint()).withHeader("Accept", "text/rdf+nt").withEntity(contentItem)).assertStatus(200).assertContentRegexp(//and the expected enhancements based on the parsed content
    "http://purl.org/dc/terms/creator.*LangIdEnhancementEngine", "http://purl.org/dc/terms/language.*en", "http://fise.iks-project.eu/ontology/entity-label.*Paris", "http://purl.org/dc/terms/creator.*org.apache.stanbol.enhancer.engines.opennlp.*EngineCore", "http://fise.iks-project.eu/ontology/entity-label.*Bob Marley", //additional enhancements based on parsed metadata
    "http://fise.iks-project.eu/ontology/entity-reference.*http://dbpedia.org/resource/Germany.*", "http://fise.iks-project.eu/ontology/entity-reference.*http://dbpedia.org/resource/NATO.*", "http://fise.iks-project.eu/ontology/entity-reference.*http://dbpedia.org/resource/Silvio_Berlusconi.*", "http://fise.iks-project.eu/ontology/entity-reference.*http://dbpedia.org/resource/Europe.*").getContent();
    log.debug("Content:\n{}\n", receivedContent);
}

